<?php
session(); include('../include/config.php'); require_once __DIR__.'/module_bootstrap.php'; hms_module_require_roles(array('admin','doctor','rekam_medis'));
if($_SERVER['REQUEST_METHOD']==='POST'){hms_module_csrf();$pid=(int)($_POST['patient_id']??0);$visit=(int)($_POST['visit_id']??0);$dest=trim($_POST['destination']??'');$diag=trim($_POST['diagnosis']??'');$reason=trim($_POST['reason']??'');if($pid>0&&$dest!==''){try{if($visit>0){$vr=hms_fetch_one($con,'SELECT patient_id FROM hms_patient_visits WHERE id=?','i',array($visit));if(!$vr||((int)$vr['patient_id']!==$pid))throw new RuntimeException('Kunjungan tidak sesuai dengan pasien.');}$st=mysqli_prepare($con,"INSERT INTO hms_referrals(patient_id,visit_id,referral_date,destination,diagnosis,reason,status) VALUES(?,?,CURDATE(),?,?,?,'DIKIRIM')");mysqli_stmt_bind_param($st,'iisss',$pid,$visit,$dest,$diag,$reason);if(mysqli_stmt_execute($st)){ $id=mysqli_stmt_insert_id($st);mysqli_stmt_close($st);hms_module_workflow_event($con,$pid,$visit?:null,null,null,'RUJUKAN','DIKIRIM','Rujukan pasien dibuat.');hms_module_audit($con,'CREATE','RUJUKAN','hms_referrals',$id,'Rujukan dibuat',null,array('patient_id'=>$pid,'visit_id'=>$visit,'destination'=>$dest,'diagnosis'=>$diag));hms_set_flash('success','Rujukan tersimpan.');}else {mysqli_stmt_close($st);throw new RuntimeException('Rujukan gagal disimpan.');}}catch(Throwable $e){hms_set_flash('danger',$e->getMessage());}}}
$patients=hms_fetch_all($con,'SELECT ID,PatientName FROM tblpatient ORDER BY PatientName LIMIT 500');$visits=hms_fetch_all($con,'SELECT id,registration_no,patient_id FROM hms_patient_visits ORDER BY id DESC LIMIT 300');$rows=hms_fetch_all($con,'SELECT r.*,p.PatientName FROM hms_referrals r LEFT JOIN tblpatient p ON p.ID=r.patient_id ORDER BY r.id DESC LIMIT 100');$role=hms_module_current_role();hms_layout_header('Rujukan',$role,'operations');
?><div class="hms-page-title"><div><h1>Rujukan</h1><div class="text-muted">Pencatatan rujukan pasien dan tujuan fasilitas/layanan.</div></div></div><div class="hms-card p-3 mb-4"><form method="post" class="row g-2"><?php echo hms_csrf_field(); ?><div class="col-md-3"><select name="patient_id" class="form-select" required><option value="">Pasien</option><?php foreach($patients as $p){ ?><option value="<?php echo (int)$p['ID']; ?>"><?php echo hms_e($p['PatientName']); ?></option><?php } ?></select></div><div class="col-md-3"><select name="visit_id" class="form-select"><option value="0">Kunjungan (opsional)</option><?php foreach($visits as $v){ ?><option value="<?php echo (int)$v['id']; ?>"><?php echo hms_e($v['registration_no']); ?></option><?php } ?></select></div><div class="col-md-2"><input name="destination" class="form-control" placeholder="Tujuan rujukan" required></div><div class="col-md-2"><input name="diagnosis" class="form-control" placeholder="Diagnosis"></div><div class="col-md-2"><input name="reason" class="form-control" placeholder="Alasan"></div><div class="col-12"><button class="btn btn-primary">Simpan Rujukan</button></div></form></div><div class="hms-card p-3"><table class="table"><thead><tr><th>Tanggal</th><th>Pasien</th><th>Tujuan</th><th>Diagnosis</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r){ ?><tr><td><?php echo hms_e($r['referral_date']); ?></td><td><?php echo hms_e($r['PatientName']); ?></td><td><?php echo hms_e($r['destination']); ?></td><td><?php echo hms_e($r['diagnosis']); ?></td><td><?php echo hms_status_badge($r['status']); ?></td></tr><?php } ?></tbody></table></div><?php hms_layout_footer(); ?>
